with lines as (select id, created_at, code from carts lateral view outer explode(coupon_codes) x as code) select code, date_trunc('day', created_at) as activity_day, size(collect_set(code)) as num_codes, count(distinct id) as distinct_ids, count(*) as num_rows, percent_rank() over (partition by code order by count(*) desc) as num_rows_percent_rank from lines group by code, activity_day order by activity_day desc nulls first;
